/* ============================================================
   MOSS — a gentle plant-care companion
   Warm, tactile, a little odd. Mobile-first.
   ============================================================ */

:root {
  --cream:      #f6efe1;
  --cream-2:    #efe4cf;
  --paper:      #fffaf0;
  --ink:        #33291f;
  --ink-soft:   #6b5b49;
  --ink-faint:  #9c8a72;
  --green:      #3f6b46;
  --green-2:    #5f9260;
  --green-3:    #7fb277;
  --green-pale: #dfe9d2;
  --clay:       #d98f5a;
  --clay-deep:  #b96a38;
  --amber:      #e8a04b;
  --rose:       #c96f6a;
  --rose-pale:  #f6ded7;
  --line:       #e0d2b9;
  --shadow:     rgba(74, 54, 33, .13);

  --r-lg: 26px;
  --r-md: 18px;
  --r-sm: 12px;

  --ease: cubic-bezier(.22, .9, .3, 1);
  --font: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Palatino, Georgia, "Times New Roman", serif;
  --font-ui: "Avenir Next", "Segoe UI", system-ui, -apple-system, "Helvetica Neue", sans-serif;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  background: var(--cream);
  color: var(--ink);
  font-family: var(--font);
  font-size: 17px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

/* soft paper texture, purely decorative */
.grain {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  opacity: .5;
  background-image:
    radial-gradient(circle at 12% 18%, rgba(216, 143, 90, .10), transparent 42%),
    radial-gradient(circle at 88% 8%, rgba(127, 178, 119, .12), transparent 40%),
    radial-gradient(circle at 75% 92%, rgba(232, 160, 75, .08), transparent 45%);
}

.shell {
  position: relative;
  z-index: 1;
  max-width: 1180px;
  margin: 0 auto;
  padding: 0 20px 60px;
}

/* ---------- focus + helpers ---------- */
.skip-link {
  position: absolute;
  left: 12px;
  top: -60px;
  background: var(--green);
  color: var(--paper);
  padding: 10px 18px;
  border-radius: 0 0 12px 12px;
  font-family: var(--font-ui);
  font-weight: 700;
  text-decoration: none;
  z-index: 100;
  transition: top .2s var(--ease);
}
.skip-link:focus { top: 0; }

:where(a, button, [tabindex]):focus-visible {
  outline: 3px solid var(--clay-deep);
  outline-offset: 3px;
  border-radius: 6px;
}

.sr-only {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

button { font-family: var(--font-ui); cursor: pointer; }
h1, h2, h3 { font-weight: 700; line-height: 1.12; margin: 0; }
p { margin: 0; }

/* ============================================================
   HEADER
   ============================================================ */
.topbar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 22px 4px 18px;
  flex-wrap: wrap;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  color: var(--ink);
}
.brand-mark { display: inline-flex; }
.brand-word {
  font-size: 27px;
  font-weight: 800;
  letter-spacing: -.02em;
}
.brand-dot { color: var(--clay); }

.topnav {
  display: flex;
  gap: 4px;
  margin-left: auto;
  background: var(--cream-2);
  padding: 5px;
  border-radius: 999px;
}
.topnav-link {
  font-family: var(--font-ui);
  font-size: 14px;
  font-weight: 600;
  color: var(--ink-soft);
  text-decoration: none;
  padding: 7px 16px;
  border-radius: 999px;
  transition: background .2s, color .2s;
}
.topnav-link:hover { color: var(--green); }
.topnav-link.is-current {
  background: var(--paper);
  color: var(--green);
  box-shadow: 0 1px 3px var(--shadow);
}

.reset-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  background: transparent;
  border: 2px solid var(--line);
  color: var(--ink-soft);
  font-size: 13px;
  font-weight: 700;
  padding: 8px 14px;
  border-radius: 999px;
  transition: border-color .2s, color .2s, transform .2s var(--ease);
}
.reset-btn:hover { border-color: var(--clay); color: var(--clay-deep); }
.reset-btn:active { transform: scale(.96); }

/* ============================================================
   LAYOUT
   ============================================================ */
.layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 30px;
  align-items: start;
}
.primary { display: grid; gap: 30px; min-width: 0; }
.sidebar { display: grid; gap: 22px; }

@media (min-width: 900px) {
  .layout { grid-template-columns: minmax(0, 1.55fr) minmax(300px, 1fr); gap: 34px; }
  .sidebar { position: sticky; top: 24px; }
}

/* ============================================================
   HERO
   ============================================================ */
.hero {
  position: relative;
  background: var(--green);
  color: var(--paper);
  border-radius: var(--r-lg);
  padding: 34px 30px 30px;
  overflow: hidden;
  display: grid;
  gap: 18px;
}
.hero::before {
  /* big soft blob */
  content: "";
  position: absolute;
  width: 360px; height: 360px;
  right: -120px; top: -160px;
  background: rgba(127, 178, 119, .28);
  border-radius: 46% 54% 60% 40% / 50% 44% 56% 50%;
}
.hero::after {
  content: "";
  position: absolute;
  width: 220px; height: 220px;
  right: 30px; bottom: -140px;
  border: 2px dashed rgba(255, 250, 240, .18);
  border-radius: 50%;
}
.hero-copy { position: relative; z-index: 2; max-width: 460px; }
.eyebrow {
  font-family: var(--font-ui);
  text-transform: uppercase;
  letter-spacing: .16em;
  font-size: 11px;
  font-weight: 800;
  color: var(--green-3);
  margin-bottom: 14px;
}
.hero h1 {
  font-size: clamp(28px, 5vw, 40px);
  letter-spacing: -.02em;
}
.hero-sub {
  margin-top: 12px;
  font-size: 16px;
  color: #e7ecd9;
  max-width: 40ch;
}
.hero-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 22px;
}
.stat-pill {
  display: inline-flex;
  align-items: baseline;
  gap: 7px;
  background: rgba(255, 250, 240, .12);
  border: 1px solid rgba(255, 250, 240, .22);
  border-radius: 999px;
  padding: 6px 14px;
  font-family: var(--font-ui);
  font-size: 13px;
}
.stat-pill b { font-size: 16px; }
.stat-pill.is-urgent { background: var(--amber); color: #4a2f13; border-color: var(--amber); }

.hero-art {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 140px;
}
.ring-wrap { position: relative; width: 120px; height: 120px; flex: none; }
.ring { transform: rotate(-90deg); }
.ring-track { fill: none; stroke: rgba(255,250,240,.18); stroke-width: 9; }
.ring-fill {
  fill: none;
  stroke: var(--amber);
  stroke-width: 9;
  stroke-linecap: round;
  stroke-dasharray: 326.7;
  stroke-dashoffset: 326.7;
  transition: stroke-dashoffset .7s var(--ease);
}
.ring-center {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.ring-count { font-size: 34px; font-weight: 800; line-height: 1; }
.ring-word {
  font-family: var(--font-ui);
  font-size: 11px;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: #cfe0c2;
}
.botanical { width: 130px; height: 130px; opacity: .95; }

@media (min-width: 620px) {
  .hero { grid-template-columns: 1fr auto; align-items: center; padding: 40px; }
  .hero-art { min-height: 170px; }
  .botanical { width: 160px; height: 160px; }
}

/* ============================================================
   QUEUE
   ============================================================ */
.queue-section { min-width: 0; }
.section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 16px;
}
.section-head h2 { font-size: 25px; }
.section-caption {
  font-size: 14px;
  color: var(--ink-faint);
  margin-top: 4px;
  font-family: var(--font-ui);
}
.count-chip {
  flex: none;
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 700;
  color: var(--green);
  background: var(--green-pale);
  border-radius: 999px;
  padding: 6px 14px;
}

.queue { list-style: none; margin: 0; padding: 0; display: grid; gap: 16px; }

.plant {
  position: relative;
  background: var(--paper);
  border: 1.5px solid var(--line);
  border-radius: var(--r-md);
  box-shadow: 0 3px 0 var(--line);
  transition: box-shadow .25s, transform .25s var(--ease), border-color .25s;
}
.plant:hover { box-shadow: 0 6px 18px var(--shadow); transform: translateY(-2px); }
.plant.is-overdue { border-color: #e4b59a; }
.plant.is-overdue::before {
  content: "";
  position: absolute;
  left: -1.5px; top: 16px; bottom: 16px;
  width: 5px;
  background: var(--rose);
  border-radius: 4px;
}
.plant.is-tomorrow { opacity: .92; }

.plant-main {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 14px;
  padding: 16px 18px 14px;
  align-items: start;
}

/* organic avatar */
.avatar {
  position: relative;
  width: 62px; height: 62px;
  flex: none;
  border-radius: 46% 54% 42% 58% / 55% 45% 55% 45%;
  display: grid;
  place-items: center;
  background: var(--green-pale);
  overflow: hidden;
}
.avatar svg { width: 46px; height: 46px; }
.avatar.a-fern    { background: #d8e6cd; }
.avatar.a-pothos  { background: #e6e2bd; }
.avatar.a-cactus  { background: #f2d9bf; }
.avatar.a-calathea{ background: #dfe0e8; }
.plant.is-overdue .avatar { animation: sway 3.5s ease-in-out infinite; }
@keyframes sway { 0%,100%{ transform: rotate(-2deg); } 50%{ transform: rotate(2deg); } }

.plant-info { min-width: 0; }
.plant-topline { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
.plant-name { font-size: 21px; }
.plant-species {
  font-family: var(--font-ui);
  font-size: 12px;
  color: var(--ink-faint);
  font-style: italic;
}
.plant-meta {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 7px;
  font-family: var(--font-ui);
  font-size: 13px;
}
.tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: var(--cream-2);
  color: var(--ink-soft);
  border-radius: 999px;
  padding: 3px 11px;
  font-weight: 600;
}
.tag-task { background: #e7efe0; color: var(--green); }
.tag-due { background: #f3e2cf; color: var(--clay-deep); }
.tag-due.is-late { background: var(--rose-pale); color: #a0433d; font-weight: 800; }
.tag-dot { width: 7px; height: 7px; border-radius: 50%; background: currentColor; }

/* actions */
.plant-actions {
  display: flex;
  gap: 10px;
  padding: 0 18px 16px 94px;
  flex-wrap: wrap;
}
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: none;
  border-radius: 999px;
  padding: 10px 18px;
  font-size: 14px;
  font-weight: 700;
  transition: transform .18s var(--ease), box-shadow .2s, background .2s;
}
.btn svg { width: 16px; height: 16px; }
.btn:active { transform: scale(.95); }
.btn-water {
  background: var(--green);
  color: var(--paper);
  box-shadow: 0 3px 0 #2c4d31;
}
.btn-water:hover { background: #365e3c; }
.btn-snooze {
  background: var(--cream-2);
  color: var(--ink-soft);
  box-shadow: 0 3px 0 var(--line);
}
.btn-snooze:hover { background: #e6d7ba; }
.btn-detail {
  background: transparent;
  color: var(--green);
  border: 2px solid var(--green-pale);
  padding: 8px 16px;
  margin-left: auto;
  font-size: 13px;
}
.btn-detail:hover { border-color: var(--green-2); background: var(--green-pale); }
.btn-detail .chev { transition: transform .25s var(--ease); }
.btn-detail[aria-expanded="true"] .chev { transform: rotate(180deg); }

/* detail panel */
.detail {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows .35s var(--ease);
}
.detail > .detail-inner { overflow: hidden; }
.detail.is-open { grid-template-rows: 1fr; }
.detail-body {
  border-top: 1.5px dashed var(--line);
  margin: 0 18px;
  padding: 16px 2px 20px;
  display: grid;
  gap: 18px;
}
.detail-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.fact {
  background: var(--cream);
  border-radius: var(--r-sm);
  padding: 12px 14px;
}
.fact-label {
  font-family: var(--font-ui);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: .12em;
  color: var(--ink-faint);
  font-weight: 800;
}
.fact-value { font-size: 16px; margin-top: 4px; }
.detail-history h4 {
  margin: 0 0 8px;
  font-family: var(--font-ui);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: .12em;
  color: var(--ink-faint);
}
.history-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.history-list li {
  position: relative;
  padding-left: 22px;
  font-size: 15px;
  font-family: var(--font-ui);
  color: var(--ink-soft);
}
.history-list li::before {
  content: "";
  position: absolute;
  left: 4px; top: 9px;
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--green-3);
  border: 2px solid var(--paper);
  box-shadow: 0 0 0 1.5px var(--green-pale);
}
.history-list li:first-child { color: var(--ink); font-weight: 600; }
.history-list li:first-child::before { background: var(--amber); }

@media (max-width: 480px) {
  .plant-actions { padding-left: 18px; }
  .btn-detail { margin-left: 0; }
}

/* ============================================================
   ALL DONE
   ============================================================ */
.all-done {
  background: var(--green-pale);
  border: 2px dashed var(--green-3);
  border-radius: var(--r-lg);
  padding: 36px 28px 32px;
  text-align: center;
}
.all-done[hidden] { display: none; }
.all-done-art { margin-bottom: 6px; }
.all-done h3 { font-size: 28px; color: var(--green); }
.all-done > p {
  max-width: 42ch;
  margin: 12px auto 0;
  color: var(--ink-soft);
  font-size: 16px;
}
.all-done-facts {
  display: flex;
  justify-content: center;
  gap: 10px;
  flex-wrap: wrap;
  margin: 22px 0;
  font-family: var(--font-ui);
}
.done-fact {
  background: var(--paper);
  border-radius: 999px;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 700;
  color: var(--green);
}
.ghost-btn {
  background: transparent;
  border: 2px solid var(--green);
  color: var(--green);
  border-radius: 999px;
  padding: 10px 22px;
  font-weight: 700;
  font-size: 14px;
  transition: background .2s, color .2s;
}
.ghost-btn:hover { background: var(--green); color: var(--paper); }

/* ============================================================
   PANELS (sidebar)
   ============================================================ */
.panel {
  background: var(--paper);
  border: 1.5px solid var(--line);
  border-radius: var(--r-md);
  padding: 22px 22px 20px;
  box-shadow: 0 3px 0 var(--line);
  position: relative;
  overflow: hidden;
}
.panel-head { margin-bottom: 4px; }
.panel-kicker {
  font-family: var(--font-ui);
  text-transform: uppercase;
  letter-spacing: .14em;
  font-size: 10px;
  font-weight: 800;
  color: var(--clay-deep);
}
.panel h2 { font-size: 21px; margin-top: 3px; }
.panel-note {
  font-size: 14px;
  color: var(--ink-faint);
  font-family: var(--font-ui);
  margin: 8px 0 18px;
}

/* rhythm */
.rhythm {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 8px;
  align-items: end;
  height: 116px;
  padding: 8px 4px 0;
}
.rhythm-day { display: flex; flex-direction: column; align-items: center; gap: 6px; height: 100%; justify-content: flex-end; }
.rhythm-stack {
  width: 100%;
  display: flex;
  flex-direction: column-reverse;
  gap: 3px;
  align-items: center;
  flex: 1;
  justify-content: flex-start;
}
.rhythm-blob {
  width: 100%;
  max-width: 26px;
  height: 13px;
  border-radius: 6px 6px 5px 5px;
  background: var(--green-2);
  animation: grow .5s var(--ease) backwards;
}
.rhythm-blob:nth-child(even) { background: var(--green-3); }
.rhythm-day.is-today .rhythm-blob { background: var(--clay); }
.rhythm-day.is-empty .rhythm-blob { display: none; }
@keyframes grow { from { transform: scaleY(0); opacity: 0; } }
.rhythm-label {
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 700;
  color: var(--ink-faint);
  text-transform: uppercase;
}
.rhythm-day.is-today .rhythm-label { color: var(--clay-deep); }
.rhythm-legend {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1.5px dashed var(--line);
  font-family: var(--font-ui);
  font-size: 12px;
  color: var(--ink-soft);
}
.legend-swatch { width: 12px; height: 12px; border-radius: 4px; background: var(--clay); flex: none; }

/* field note */
.note-panel { background: #fbeacf; border-color: #e9d2a8; }
.note-panel::after {
  content: "";
  position: absolute;
  right: -30px; top: -30px;
  width: 90px; height: 90px;
  border: 2px dashed rgba(185, 106, 56, .25);
  border-radius: 50%;
}
.note-stamp {
  font-family: var(--font-ui);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--clay-deep);
  border: 1.5px solid var(--clay-deep);
  display: inline-block;
  padding: 3px 10px;
  border-radius: 4px;
  transform: rotate(-3deg);
  margin-bottom: 14px;
}
.note-panel h2 { font-size: 20px; }
.note-panel > p { font-size: 15px; margin-top: 10px; color: #5b482f; }
.note-panel em { color: var(--clay-deep); }
.note-doodle { display: flex; justify-content: flex-end; margin-top: 4px; opacity: .8; }

/* activity log */
.log { list-style: none; margin: 14px 0 0; padding: 0; display: grid; gap: 12px; }
.log li {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 10px;
  align-items: start;
  font-family: var(--font-ui);
  font-size: 14px;
  color: var(--ink-soft);
}
.log-mark {
  width: 26px; height: 26px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 13px;
  flex: none;
  background: var(--green-pale);
  color: var(--green);
}
.log-mark.snooze { background: #f3e2cf; color: var(--clay-deep); }
.log-mark.undo { background: var(--rose-pale); color: #a0433d; }
.log-time { display: block; font-size: 11px; color: var(--ink-faint); margin-top: 2px; }
.log-empty { color: var(--ink-faint); font-style: italic; font-family: var(--font); }

/* ============================================================
   FOOTER
   ============================================================ */
.footer {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 40px;
  padding-top: 18px;
  border-top: 1.5px dashed var(--line);
  font-family: var(--font-ui);
  font-size: 12px;
  color: var(--ink-faint);
}

/* ============================================================
   TOAST
   ============================================================ */
.toast {
  position: fixed;
  z-index: 50;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%) translateY(20px);
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: calc(100vw - 32px);
  background: var(--ink);
  color: var(--paper);
  padding: 12px 12px 12px 18px;
  border-radius: 999px;
  box-shadow: 0 10px 30px rgba(51,41,31,.3);
  font-family: var(--font-ui);
  font-size: 14px;
  opacity: 0;
  transition: opacity .3s, transform .3s var(--ease);
}
.toast[hidden] { display: none; }
.toast.is-visible { opacity: 1; transform: translateX(-50%) translateY(0); }
.toast-icon { font-size: 17px; }
.toast-msg { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.toast-undo {
  background: var(--amber);
  color: #3a2510;
  border: none;
  border-radius: 999px;
  padding: 7px 15px;
  font-weight: 800;
  font-size: 13px;
  flex: none;
}
.toast-undo:hover { background: #f0b25f; }
.toast-close {
  background: transparent;
  border: none;
  color: #cbbfae;
  font-size: 20px;
  line-height: 1;
  width: 28px; height: 28px;
  border-radius: 50%;
  flex: none;
}
.toast-close:hover { color: var(--paper); background: rgba(255,255,255,.12); }

/* ============================================================
   REDUCED MOTION
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
  .plant.is-overdue .avatar { animation: none; }
}

/* ============================================================
   MOSS — a gentle plant-care companion
   Vanilla JS. No network, no storage of anything sensitive.
   Data is inlined from PLANTS.json so the page works from file://.
   ============================================================ */
(function () {
  "use strict";

  var DATA = {
    plants: [
      { id: "fern", name: "Frida", species: "Boston fern", location: "Bathroom", task: "Water", due: "2 days overdue", urgency: 4, light: "Low, indirect", history: ["Sep 19 · Misted", "Sep 16 · Watered", "Sep 12 · New frond"] },
      { id: "pothos", name: "Orbit", species: "Golden pothos", location: "Bookshelf", task: "Rotate", due: "Today", urgency: 2, light: "Medium, indirect", history: ["Sep 20 · Watered", "Sep 14 · Rotated", "Sep 10 · Wiped leaves"] },
      { id: "cactus", name: "Dot", species: "Bunny ears cactus", location: "South window", task: "Check soil", due: "Today", urgency: 1, light: "Bright, direct", history: ["Sep 08 · Watered", "Sep 01 · New pad noted", "Aug 22 · Rotated"] },
      { id: "calathea", name: "Drama", species: "Calathea orbifolia", location: "Bedroom", task: "Mist", due: "Tomorrow", urgency: 0, light: "Medium, filtered", history: ["Sep 21 · Misted", "Sep 18 · Watered", "Sep 15 · Brown edge noted"] }
    ],
    week: [1, 3, 2, 4, 2, 1, 3]
  };

  var STORE_KEY = "moss.day.v1";
  var DAY_LABELS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
  var TODAY_INDEX = 3; // "Thu" — the day of this gentle fiction

  /* Each plant's mutable day-state: status + care points. */
  function freshState() {
    return {
      plants: {
        fern:     { status: "pending", points: 4 },
        pothos:   { status: "pending", points: 2 },
        cactus:   { status: "pending", points: 1 },
        calathea: { status: "pending", points: 0 }
      },
      log: [],
      doneCount: 0
    };
  }

  var state = load();
  var lastAction = null;   // single-step undo
  var toastTimer = null;
  var openDetailId = null;

  /* ---------- persistence (best-effort; file:// safe) ---------- */
  function load() {
    try {
      var raw = localStorage.getItem(STORE_KEY);
      if (raw) {
        var s = JSON.parse(raw);
        if (s && s.plants && s.log) return s;
      }
    } catch (e) { /* private mode / file:// — just stay in memory */ }
    return freshState();
  }
  function save() {
    try { localStorage.setItem(STORE_KEY, JSON.stringify(state)); } catch (e) {}
  }

  /* ---------- helpers ---------- */
  function $(id) { return document.getElementById(id); }
  function esc(str) {
    return String(str).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }
  function dueRank(due) {
    if (due.indexOf("overdue") !== -1) return 3;
    if (due.indexOf("Today") !== -1) return 2;
    if (due.indexOf("Tomorrow") !== -1) return 1;
    return 0;
  }
  function isOverdue(p) { return p.due.indexOf("overdue") !== -1 && state.plants[p.id].status === "pending"; }
  function nowLabel() {
    return new Date().toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
  }
  function prefersReducedMotion() {
    return window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  }

  /* ---------- little inline plant illustrations ---------- */
  function plantSVG(id) {
    switch (id) {
      case "fern":
        return '<svg viewBox="0 0 48 48" aria-hidden="true" focusable="false"><path d="M24 42V14" stroke="#3f6b46" stroke-width="2.5" stroke-linecap="round" fill="none"/><path d="M24 20C16 18 10 14 9 8c8 1 14 5 15 12zM24 26c8-2 14-6 15-12-8 1-14 5-15 12zM24 32c-7-2-12-5-13-11 7 1 12 4 13 11zM24 36c6-1 11-4 12-9-6 1-11 3-12 9z" fill="#5f9260"/><circle cx="24" cy="12" r="2.5" fill="#e8a04b"/></svg>';
      case "pothos":
        return '<svg viewBox="0 0 48 48" aria-hidden="true" focusable="false"><path d="M14 8C14 22 20 32 34 40" stroke="#3f6b46" stroke-width="2.5" fill="none" stroke-linecap="round"/><path d="M16 12c-7 0-11 4-11 10 7 0 11-4 11-10zM22 24c8-1 13 3 13 10-8 1-13-3-13-10zM29 34c-1 7 2 11 8 12 1-7-2-11-8-12z" fill="#7aa863"/><path d="M16 12c-7 0-11 4-11 10 7 0 11-4 11-10z" fill="#a9c66e"/></svg>';
      case "cactus":
        return '<svg viewBox="0 0 48 48" aria-hidden="true" focusable="false"><path d="M19 42V18a5 5 0 0 1 10 0v24" fill="#6aa06a" stroke="#3f6b46" stroke-width="2"/><path d="M19 26c-6 0-8-4-8-9 0-4 3-6 6-6 0 5 1 10 2 15z" fill="#7fb277" stroke="#3f6b46" stroke-width="2"/><path d="M29 30c6 0 8-4 8-9 0-4-3-6-6-6 0 5-1 10-2 15z" fill="#5f9260" stroke="#3f6b46" stroke-width="2"/><path d="M16 42h16" stroke="#b96a38" stroke-width="3" stroke-linecap="round"/><circle cx="22" cy="16" r="1" fill="#fff"/><circle cx="27" cy="20" r="1" fill="#fff"/></svg>';
      case "calathea":
        return '<svg viewBox="0 0 48 48" aria-hidden="true" focusable="false"><path d="M24 42V18" stroke="#3f6b46" stroke-width="2.5" stroke-linecap="round" fill="none"/><ellipse cx="24" cy="16" rx="15" ry="9" transform="rotate(-18 24 16)" fill="#7f9c86"/><ellipse cx="24" cy="16" rx="15" ry="9" transform="rotate(-18 24 16)" fill="none" stroke="#3f6b46" stroke-width="1.5"/><path d="M12 20l24-8" stroke="#dfe9d2" stroke-width="1" stroke-dasharray="2 2"/><path d="M24 42c-6-4-9-9-9-14M24 42c6-4 9-9 9-14" stroke="#3f6b46" stroke-width="1.5" fill="none"/></svg>';
    }
    return "";
  }

  var ICON_WATER = '<svg viewBox="0 0 20 20" aria-hidden="true" focusable="false"><path d="M10 2C7 6 4 9 4 12a6 6 0 0 0 12 0c0-3-3-6-6-10z" fill="currentColor"/><path d="M7 12a3 3 0 0 0 3 3" stroke="#fff" stroke-width="1.4" fill="none" stroke-linecap="round" opacity=".8"/></svg>';
  var ICON_SNOOZE = '<svg viewBox="0 0 20 20" aria-hidden="true" focusable="false"><circle cx="10" cy="10" r="8" fill="none" stroke="currentColor" stroke-width="1.8"/><path d="M10 5v5l3 2" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>';
  var CHEVRON = '<svg class="chev" viewBox="0 0 20 20" width="14" height="14" aria-hidden="true" focusable="false"><path d="M4 7l6 6 6-6" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';

  /* ============================================================
     RENDER
     ============================================================ */
  function render() {
    renderHero();
    renderQueue();
    renderRhythm();
    renderLog();
    renderAllDone();
  }

  function pendingPlants() {
    return DATA.plants.filter(function (p) { return state.plants[p.id].status === "pending"; });
  }
  function completedPlants() {
    return DATA.plants.filter(function (p) { return state.plants[p.id].status === "done"; });
  }

  function renderHero() {
    var pending = pendingPlants();
    var overdue = pending.filter(function (p) { return dueRank(p.due) === 3; });
    var today = pending.filter(function (p) { return dueRank(p.due) === 2; });
    var remaining = pending.length;
    var done = DATA.plants.length - remaining;

    $("todayLabel").textContent = "Care queue · Thursday, 21 September";
    $("queueCaption").textContent = remaining
      ? overdue.length
        ? overdue.length + " waiting patiently (but overdue) — let's start there."
        : "Sorted by who's been waiting longest."
      : "Nothing left in the queue. Nicely done.";

    var pills = "";
    if (remaining === 0) {
      pills = '<span class="stat-pill"><b>All done</b> · every plant tended</span>';
    } else {
      if (overdue.length) pills += '<span class="stat-pill is-urgent"><b>' + overdue.length + '</b> overdue</span>';
      if (today.length) pills += '<span class="stat-pill"><b>' + today.length + '</b> due today</span>';
      pills += '<span class="stat-pill"><b>' + done + '</b> already cared for</span>';
    }
    $("heroStats").innerHTML = pills;

    $("ringCount").textContent = remaining;
    var ring = $("ringFill");
    var circumference = 2 * Math.PI * 52;
    var fraction = DATA.plants.length ? done / DATA.plants.length : 0;
    ring.style.strokeDashoffset = String(circumference * (1 - fraction));
    ring.setAttribute("aria-hidden", "true");

    $("queueChip").textContent = remaining
      ? remaining + (remaining === 1 ? " plant" : " plants") + " to tend"
      : "All clear";

    $("heroSub").textContent = remaining === 0
      ? "Every plant is looked after. Go enjoy your day — they're quietly photosynthesising."
      : "Your plants are doing their best. Here's who could use a hand today.";
  }

  function renderQueue() {
    var pending = pendingPlants().sort(function (a, b) {
      var d = dueRank(b.due) - dueRank(a.due);
      return d !== 0 ? d : b.urgency - a.urgency;
    });

    var html = pending.map(function (p, i) {
      var late = isOverdue(p);
      var tomorrow = p.due.indexOf("Tomorrow") !== -1;
      var detailOpen = openDetailId === p.id;
      var st = state.plants[p.id];

      var dueClass = late ? "tag-due is-late" : "tag-due";
      var cls = "plant" + (late ? " is-overdue" : "") + (tomorrow ? " is-tomorrow" : "");

      var detailId = "detail-" + p.id;
      var historyHTML = p.history.map(function (h) {
        return "<li>" + esc(h) + "</li>";
      }).join("");
      var logEntries = (state.log || []).filter(function (e) { return e.plantId === p.id && e.kind !== "undo"; })
        .slice(0, 1);
      if (logEntries.length) {
        historyHTML = "<li>" + esc(logEntries[0].text) + "</li>" + historyHTML;
      }
      if (st.status === "snoozed") {
        historyHTML = "<li>Snoozed until tomorrow</li>" + historyHTML;
      }

      return '' +
        '<li class="' + cls + '" data-id="' + p.id + '">' +
          '<div class="plant-main">' +
            '<span class="avatar a-' + p.id + '" aria-hidden="true">' + plantSVG(p.id) + '</span>' +
            '<div class="plant-info">' +
              '<div class="plant-topline">' +
                '<span class="plant-name">' + esc(p.name) + '</span>' +
                '<span class="plant-species">' + esc(p.species) + '</span>' +
              '</div>' +
              '<div class="plant-meta">' +
                '<span class="tag tag-task"><span class="tag-dot"></span>' + esc(p.task) + '</span>' +
                '<span class="tag ' + dueClass + '">' + esc(p.due) + '</span>' +
                '<span class="tag">' + esc(p.location) + '</span>' +
              '</div>' +
            '</div>' +
          '</div>' +
          '<div class="plant-actions">' +
            '<button class="btn btn-water" type="button" data-action="water" data-id="' + p.id + '">' +
              ICON_WATER + ' Mark done' +
            '</button>' +
            '<button class="btn btn-snooze" type="button" data-action="snooze" data-id="' + p.id + '">' +
              ICON_SNOOZE + ' Snooze' +
            '</button>' +
            '<button class="btn btn-detail" type="button" data-action="detail" data-id="' + p.id + '" ' +
              'aria-expanded="' + detailOpen + '" aria-controls="' + detailId + '">' +
              'Care notes ' + CHEVRON +
            '</button>' +
          '</div>' +
          '<div class="detail' + (detailOpen ? " is-open" : "") + '" id="' + detailId + '">' +
            '<div class="detail-inner"><div class="detail-body">' +
              '<div class="detail-grid">' +
                '<div class="fact"><div class="fact-label">Light</div><div class="fact-value">' + esc(p.light) + '</div></div>' +
                '<div class="fact"><div class="fact-label">Water / care</div><div class="fact-value">' + esc(p.task) + ' · ' + esc(p.due.toLowerCase()) + '</div></div>' +
              '</div>' +
              '<div class="detail-history"><h4>Observation history</h4>' +
                '<ul class="history-list">' + historyHTML + '</ul>' +
              '</div>' +
            '</div></div>' +
          '</div>' +
        '</li>';
    }).join("");

    $("queue").innerHTML = html;
  }

  function renderRhythm() {
    var max = Math.max.apply(null, DATA.week);
    var html = DATA.week.map(function (n, i) {
      var blobs = "";
      for (var b = 0; b < n; b++) {
        blobs += '<span class="rhythm-blob" style="animation-delay:' + (i * 40 + b * 60) + 'ms"></span>';
      }
      var classes = "rhythm-day" + (i === TODAY_INDEX ? " is-today" : "") + (n === 0 ? " is-empty" : "");
      return '<div class="' + classes + '">' +
        '<div class="rhythm-stack">' + blobs + '</div>' +
        '<span class="rhythm-label">' + DAY_LABELS[i] + '</span>' +
      '</div>';
    }).join("");
    $("rhythm").innerHTML = html;

    var total = DATA.week.reduce(function (a, b) { return a + b; }, 0);
    $("rhythm").setAttribute("aria-label",
      "Care moments this week, Monday to Sunday: " +
      DATA.week.map(function (n, i) { return DAY_LABELS[i] + " " + n; }).join(", ") +
      ". Busiest day is " + DAY_LABELS[DATA.week.indexOf(max)] + " with " + max + ". " + total + " moments total.");
    $("rhythmLegend").innerHTML =
      '<span class="legend-swatch" aria-hidden="true"></span>' +
      '<span>Today is <b>Thursday</b> · ' + total + ' little moments this week</span>';
  }

  function renderLog() {
    var entries = (state.log || []).slice(0, 5);
    if (!entries.length) {
      $("log").innerHTML = '<li class="log-empty">No care logged yet today. The queue is your starting point.</li>';
      return;
    }
    $("log").innerHTML = entries.map(function (e) {
      var mark = e.kind === "water" ? "✓" : e.kind === "snooze" ? "z" : "↺";
      var cls = e.kind === "snooze" ? " snooze" : e.kind === "undo" ? " undo" : "";
      return '<li><span class="log-mark' + cls + '" aria-hidden="true">' + mark + '</span>' +
        '<span>' + esc(e.text) + '<span class="log-time">' + esc(e.time) + '</span></span></li>';
    }).join("");
  }

  function renderAllDone() {
    var remaining = pendingPlants().length;
    var done = completedPlants().length;
    var snoozed = DATA.plants.filter(function (p) { return state.plants[p.id].status === "snoozed"; }).length;
    var box = $("allDone");
    if (remaining > 0) {
      box.hidden = true;
      $("queue").hidden = false;
      return;
    }
    box.hidden = false;
    $("queue").hidden = true;
    $("allDoneFacts").innerHTML =
      '<span class="done-fact">' + done + ' cared for</span>' +
      (snoozed ? '<span class="done-fact">' + snoozed + ' snoozed</span>' : "") +
      '<span class="done-fact">Next check-in tomorrow</span>';
  }

  /* ============================================================
     ACTIONS
     ============================================================ */
  function addLog(kind, text, plantId) {
    if (!state.log) state.log = [];
    state.log.unshift({ kind: kind, text: text, plantId: plantId || null, time: nowLabel() });
    if (state.log.length > 12) state.log.length = 12;
  }

  function act(action, id) {
    var plant = DATA.plants.filter(function (p) { return p.id === id; })[0];
    if (!plant) return;
    var st = state.plants[id];
    if (st.status !== "pending") return;

    // snapshot for single-step undo
    lastAction = {
      id: id,
      prevStatus: st.status,
      prevPoints: st.points,
      prevLogLen: state.log.length,
      prevDone: state.doneCount,
      action: action
    };

    if (action === "water") {
      st.status = "done";
      st.points = 0;
      state.doneCount = (state.doneCount || 0) + 1;
      addLog("water", "Marked " + plant.name + " done · " + plant.task, id);
      announce(plant.name + " marked done. Undo available.");
      showToast("💧", plant.name + " is all cared for. Lovely.", true);
    } else if (action === "snooze") {
      st.status = "snoozed";
      st.points = 0;
      addLog("snooze", "Snoozed " + plant.name + " until tomorrow", id);
      announce(plant.name + " snoozed until tomorrow. Undo available.");
      showToast("🌙", plant.name + " snoozed until tomorrow.", true);
    }
    save();
    render();
    refocusAfterAction(id, action);
  }

  /* After an action the button disappears; move focus somewhere sensible. */
  function refocusAfterAction(id, action) {
    var pending = pendingPlants();
    var focusTarget;
    if (pending.length) {
      // focus the same-position action button of the next pending plant
      var next = pending[0];
      focusTarget = document.querySelector('.plant[data-id="' + next.id + '"] [data-action="' + action + '"]');
    }
    if (!focusTarget) focusTarget = $("undoBtn");
    if (focusTarget && !focusTarget.hidden && focusTarget.offsetParent !== null) {
      focusTarget.focus();
    }
  }

  function undoLast() {
    if (!lastAction) return;
    var u = lastAction;
    var st = state.plants[u.id];
    var plant = DATA.plants.filter(function (p) { return p.id === u.id; })[0];
    st.status = u.prevStatus;
    st.points = u.prevPoints;
    state.doneCount = u.prevDone;
    if (state.log && state.log.length > u.prevLogLen) {
      state.log.splice(0, state.log.length - u.prevLogLen);
    }
    addLog("undo", "Undid " + (u.action === "water" ? "mark done" : "snooze") + " for " + (plant ? plant.name : "plant"), u.id);
    lastAction = null;
    save();
    render();
    hideToast();
    announce("Action undone. " + (plant ? plant.name : "The plant") + " is back in the queue.");
    var btn = document.querySelector('.plant[data-id="' + u.id + '"] [data-action="' + u.action + '"]');
    if (btn) btn.focus();
  }

  function toggleDetail(id) {
    openDetailId = openDetailId === id ? null : id;
    renderQueue();
    var btn = document.querySelector('.plant[data-id="' + id + '"] [data-action="detail"]');
    if (btn) btn.setAttribute("aria-expanded", String(openDetailId === id));
    announce(openDetailId === id ? "Care notes expanded." : "Care notes collapsed.");
  }

  function resetDay() {
    state = freshState();
    lastAction = null;
    openDetailId = null;
    save();
    render();
    hideToast();
    announce("Day reset. All four plants are back in the queue.");
  }

  function undoAll() {
    state = freshState();
    lastAction = null;
    save();
    render();
    announce("Queue restored. All four plants are back.");
    var first = document.querySelector('.plant [data-action="detail"]');
    if (first) first.focus();
  }

  /* ============================================================
     TOAST
     ============================================================ */
  function showToast(icon, msg, withUndo) {
    var toast = $("toast");
    $("toastIcon").textContent = icon;
    $("toastMsg").textContent = msg;
    $("undoBtn").hidden = !withUndo;
    toast.hidden = false;
    // force reflow so transition runs
    void toast.offsetWidth;
    toast.classList.add("is-visible");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(hideToast, 6000);
  }
  function hideToast() {
    var toast = $("toast");
    toast.classList.remove("is-visible");
    clearTimeout(toastTimer);
    var delay = prefersReducedMotion() ? 0 : 300;
    toastTimer = setTimeout(function () { toast.hidden = true; }, delay);
  }

  /* ============================================================
     ANNOUNCER
     ============================================================ */
  function announce(msg) {
    var el = $("announcer");
    el.textContent = "";
    setTimeout(function () { el.textContent = msg; }, 40);
  }

  /* ============================================================
     EVENTS (delegation + keyboard friendly)
     ============================================================ */
  document.addEventListener("click", function (e) {
    var target = e.target.closest ? e.target.closest("[data-action]") : null;
    if (target) {
      var action = target.getAttribute("data-action");
      var id = target.getAttribute("data-id");
      if (action === "water" || action === "snooze") act(action, id);
      else if (action === "detail") toggleDetail(id);
      return;
    }
    if (e.target.closest && e.target.closest("#undoBtn")) { undoLast(); return; }
    if (e.target.closest && e.target.closest("#toastClose")) { hideToast(); return; }
    if (e.target.closest && e.target.closest("#resetBtn")) { resetDay(); return; }
    if (e.target.closest && e.target.closest("#undoAllBtn")) { undoAll(); return; }
  });

  // Keyboard: Escape closes toast or collapses an open detail panel.
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape") {
      if (!$("toast").hidden) { hideToast(); return; }
      if (openDetailId) {
        var id = openDetailId;
        toggleDetail(id);
        var btn = document.querySelector('.plant[data-id="' + id + '"] [data-action="detail"]');
        if (btn) btn.focus();
      }
    }
  });

  // Keep nav "current" honest as sections come into view via scroll/hash.
  var navLinks = Array.prototype.slice.call(document.querySelectorAll(".topnav-link"));
  navLinks.forEach(function (link) {
    link.addEventListener("click", function () {
      navLinks.forEach(function (l) { l.classList.remove("is-current"); l.removeAttribute("aria-current"); });
      link.classList.add("is-current");
      link.setAttribute("aria-current", "page");
    });
  });

  /* ---------- go ---------- */
  render();
})();

